package com.phoenix.business.repository; import com.phoenix.business.domain.AuditLog; import org.springframework.data.jpa.repository.*; import org.springframework.data.repository.query.Param; import org.springframework.data.domain.*; public interface AuditLogRepository extends JpaRepository<AuditLog,Long>{@Query("select a from AuditLog a where (:q is null or lower(a.actorUsername) like lower(concat('%',:q,'%')) or lower(a.action) like lower(concat('%',:q,'%')) or lower(coalesce(a.summary,'')) like lower(concat('%',:q,'%'))) order by a.createdAt desc") Page<AuditLog> search(@Param("q") String q,Pageable p);}
